fn advance_tail_finish_inductive(pre: Self, post: Self, node_id: NodeId, new_tail: nat) {
    assert(pre.inv_buffer_contents());
    assert(pre.all_combiner_valid());
    assert(post.all_combiner_valid()) by {
        assert forall |n| post.combiner.contains_key(n) ==> post.combiner_valid(n, post.combiner[n]) by {
            if n == node_id {
                assert(post.combiner[n] === CombinerState::Appending { cur_idx: pre.tail, tail: new_tail });
                assert(pre.tail <= new_tail);
                assert(new_tail <= post.tail);
                assert((post.tail as int) - (post.buffer_size as int) <= pre.tail <= (post.tail as int));
                assert forall |i: nat| pre.tail <= i < new_tail ==> !log_entry_is_alive(post.alive_bits, i as int, post.buffer_size) by {
                    assert(log_entry_is_alive(post.alive_bits, i as int, post.buffer_size) == log_entry_is_alive(pre.alive_bits, i as int, pre.buffer_size));
                };
            } else {
                assert(post.combiner[n] === pre.combiner[n]);
                assert(pre.combiner_valid(n, pre.combiner[n]));
            }
        };
    };
    assert(post.inv_buffer_contents()) by {
        assert forall |i: int| post.tail - post.buffer_size <= i < post.tail ==> (
            (log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
                i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat))
            <==> post.contents.contains_key(i)) by {
            assert(post.contents.contains_key(i) == pre.contents.contains_key(i));
        };
        assert forall |i: int| post.tail <= i ==> !post.contents.contains_key(i) by {
            assert(post.contents.contains_key(i) == pre.contents.contains_key(i));
        };
    };
}

