fn advance_tail_finish_inductive(pre: Self, post: Self, node_id: NodeId, new_tail: nat) {
    assert(pre.inv_buffer_contents());
    assert(pre.all_combiner_valid());
    assert(pre.combiner.contains_key(node_id));
    assert(pre.combiner[node_id].is_AdvancingTail());
    assert forall |n| 0 <= n < pre.num_replicas ==> pre.local_versions.contains_key(n);
    assert(pre.combiner[node_id].get_AdvancingTail_observed_head() <= pre.local_versions[0]);
    assert(pre.local_versions[node_id] <= pre.tail);
    assert(pre.tail - pre.buffer_size <= pre.local_versions[node_id]);
    assert(new_tail <= pre.combiner[node_id].get_AdvancingTail_observed_head() + pre.buffer_size);
    assert(pre.combiner[node_id].get_AdvancingTail_observed_head() <= pre.tail);
    assert(post.all_combiner_valid()) by {
        assert forall |n| #![trigger post.combiner.contains_key(n)]
            post.combiner.contains_key(n) implies post.combiner_valid(n, post.combiner[n]) by {
            if n == node_id {
                assert(post.combiner[n] === CombinerState::Appending { cur_idx: pre.tail, tail: new_tail });
                assert(pre.tail <= new_tail);
                assert((post.tail as int) - (post.buffer_size as int) <= pre.tail <= (post.tail as int));
                assert forall |i: nat| pre.tail <= i < new_tail implies
                    !log_entry_is_alive(post.alive_bits, i as int, post.buffer_size) by {
                    assert(log_entry_is_alive(post.alive_bits, i as int, post.buffer_size) ==
                        log_entry_is_alive(pre.alive_bits, i as int, pre.buffer_size));
                    let min_local_head = map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat);
                    map_min_value_smallest(pre.local_versions, (pre.num_replicas - 1) as nat);
                };
            } else {
                assert(post.combiner[n] === pre.combiner[n]);
                assert(pre.combiner.contains_key(n));
                assert(pre.combiner_valid(n, pre.combiner[n]));
            }
        };
    };
    assert(post.inv_buffer_contents()) by {
